// ---------------------------------------------------------------------------------------------
// S1: the usermod must see its own topics after WLED strips the device prefix.
// ---------------------------------------------------------------------------------------------
static void testClassifyTopic() {
  using pixc::Topic;
  const char* base = "epixc/v1/d/aabbccddeeff";

  // What WLED actually delivers (mqtt.cpp strips mqttDeviceTopic). This is the case that was dead.
  CHECK(pixc::classifyTopic("/cfg", base) == Topic::Cfg);
  CHECK(pixc::classifyTopic("/reset", base) == Topic::Reset);
  CHECK(pixc::classifyTopic("/ota", base) == Topic::Ota);

  // The unstripped form, for a delivery path that does not strip.
  CHECK(pixc::classifyTopic("epixc/v1/d/aabbccddeeff/cfg", base) == Topic::Cfg);
  CHECK(pixc::classifyTopic("epixc/v1/d/aabbccddeeff/ota", base) == Topic::Ota);

  // Exact match only: our own publish topic is not a command, and near-misses are nothing.
  CHECK(pixc::classifyTopic("/ota/progress", base) == Topic::None);
  CHECK(pixc::classifyTopic("epixc/v1/d/aabbccddeeff/ota/progress", base) == Topic::None);
  CHECK(pixc::classifyTopic("/cfgX", base) == Topic::None);
  CHECK(pixc::classifyTopic("/api", base) == Topic::None);
  CHECK(pixc::classifyTopic("", base) == Topic::None);
  CHECK(pixc::classifyTopic(nullptr, base) == Topic::None);

  // Another device's topic must never match, stripped or not.
  CHECK(pixc::classifyTopic("epixc/v1/d/001122334455/cfg", base) == Topic::None);

  // The old matcher's bug, pinned: a strstr for the FULL topic inside "/cfg" can never succeed.
  CHECK(std::strstr("/cfg", "epixc/v1/d/aabbccddeeff/cfg") == nullptr);

  // No base configured: only the stripped form can match.
  CHECK(pixc::classifyTopic("/reset", "") == Topic::Reset);
  CHECK(pixc::classifyTopic("/reset", nullptr) == Topic::Reset);

  // The light's energy and live power (2026-10-18). `/energy` is what it publishes, not a command.
  CHECK(pixc::classifyTopic("/live", base) == Topic::Live);
  CHECK(pixc::classifyTopic("/energy/ack", base) == Topic::EnergyAck);
  CHECK(pixc::classifyTopic("epixc/v1/d/aabbccddeeff/energy/ack", base) == Topic::EnergyAck);
  CHECK(pixc::classifyTopic("/energy", base) == Topic::None);
  CHECK(pixc::classifyTopic("/power", base) == Topic::None);
  CHECK(pixc::classifyTopic("/energy/ackX", base) == Topic::None);
}

// ---------------------------------------------------------------------------------------------
// Energy kept on the light: hours, rollover, the 72-hour ring, the payload, the ack.
// ---------------------------------------------------------------------------------------------
static void testEnergyLog() {
  const uint32_t h0 = 1792332000;   // a whole hour (1792332000 % 3600 == 0)
  CHECK(h0 % 3600 == 0);

  // Before the clock is set nothing is measured, and nothing is filed under 1970.
  {
    pixc::EnergyLog log;
    CHECK(!log.add(1000, 2.0f, 1.0f));
    CHECK(log.open.t == 0 && log.count == 0);
  }

  // One amp for a full hour is one amp-hour over 3600 measured seconds, filed when the next hour
  // starts.
  {
    pixc::EnergyLog log;
    for (uint32_t i = 0; i < 3600; i++) CHECK(!log.add(h0 + i, 1.0f, 1.0f) || i == 0);
    CHECK(log.open.t == h0);
    CHECK(log.count == 0);
    CHECK(log.add(h0 + 3600, 0.5f, 1.0f));
    CHECK(log.count == 1);
    CHECK(log.closed[0].t == h0);
    CHECK(std::fabs(log.closed[0].ah - 1.0f) < 0.01f);
    CHECK(log.closed[0].s == 3600);
    CHECK(log.open.t == h0 + 3600);
  }

  // Samples at 1.3 s are not rounded away second by second.
  {
    pixc::EnergyLog log;
    for (int i = 0; i < 1000; i++) log.add(h0 + 10 + (uint32_t)(i * 1.3), 1.0f, 1.3f);
    CHECK(log.open.s >= 1299 && log.open.s <= 1301);
  }

  // A light switched off at the wall: the partial hour saved before the cut is filed by the first
  // sample after it, hours later, with the seconds it actually measured.
  {
    pixc::EnergyLog log;
    for (uint32_t i = 0; i < 600; i++) log.add(h0 + i, 2.0f, 1.0f);
    pixc::EnergyLog restored;
    restored.open = log.open;
    restored.openSecs = log.openSecs;
    CHECK(restored.add(h0 + 5 * 3600 + 7, 1.0f, 1.0f));
    CHECK(restored.count == 1 && restored.closed[0].t == h0 && restored.closed[0].s == 600);
    CHECK(std::fabs(restored.closed[0].ah - 2.0f * 600 / 3600) < 0.001f);
    CHECK(restored.open.t == h0 + 5 * 3600);
  }

  // An hour with nothing measured is not filed (the server refuses s = 0).
  {
    pixc::EnergyLog log;
    log.add(h0 + 5, 1.0f, 0.0f);
    CHECK(!log.add(h0 + 3600, 1.0f, 1.0f));
    CHECK(log.count == 0);
  }

  // Seconds never pass 3600, whatever the samples claim.
  {
    pixc::EnergyLog log;
    log.add(h0 + 1, 1.0f, 5000.0f);
    CHECK(log.open.s == 3600);
  }

  // Negative or NaN current counts as none.
  {
    pixc::EnergyLog log;
    log.add(h0 + 1, -3.0f, 10.0f);
    log.add(h0 + 2, std::nanf(""), 10.0f);
    CHECK(log.open.ah == 0.0f && log.open.s == 20);
  }

  // The ring keeps the newest 72 hours.
  {
    pixc::EnergyLog log;
    for (uint32_t h = 0; h < 80; h++) log.add(h0 + h * 3600 + 1, 1.0f, 60.0f);
    log.closeOpen();
    CHECK(log.count == 72);
    CHECK(log.closed[0].t == h0 + 8 * 3600);
    CHECK(log.closed[71].t == h0 + 79 * 3600);
  }

  // The same hour filed twice in a row (the clock stepped back) is one hour.
  {
    pixc::EnergyLog log;
    log.push({h0, 0.25f, 900});
    log.push({h0, 0.25f, 3000});
    CHECK(log.count == 1 && log.closed[0].s == 3600 && std::fabs(log.closed[0].ah - 0.5f) < 1e-6f);
  }

  // The payload: the oldest 24, oldest first, and the newest t in it; the server's shape.
  {
    pixc::EnergyLog log;
    for (uint32_t h = 0; h < 30; h++) log.push({h0 + h * 3600, 0.4213f, 3600});
    char buf[pixc::kEnergyPayloadMax];
    uint32_t newest = 0;
    const size_t n = log.format(buf, sizeof(buf), &newest);
    CHECK(n > 0 && n < sizeof(buf));
    CHECK(newest == h0 + 23 * 3600);
    const char* head = "{\"buckets\":[{\"t\":1792332000,\"ah\":0.4213,\"s\":3600},";
    CHECK(std::strncmp(buf, head, std::strlen(head)) == 0);
    StaticJsonDocument<4096> doc;
    CHECK(!deserializeJson(doc, buf));
    CHECK(doc["buckets"].size() == 24);
    CHECK(doc["buckets"][23]["t"].as<uint32_t>() == h0 + 23 * 3600);
    // Too small a buffer gets nothing rather than half a message.
    char small[64];
    CHECK(log.format(small, sizeof(small), &newest) == 0);
    // At the widest every field can be, the payload still fits.
    pixc::EnergyLog wide;
    for (uint32_t h = 0; h < 24; h++) wide.push({0xFFFFFFF0u - (23 - h) * 3600, 1e9f, 3600});
    CHECK(wide.format(buf, sizeof(buf), &newest) > 0);
    CHECK(!deserializeJson(doc, buf));
    CHECK(doc["buckets"][0]["ah"].as<float>() <= 99.0f);
  }

  // The ack forgets every hour up to `through`, and only those.
  {
    pixc::EnergyLog log;
    for (uint32_t h = 0; h < 5; h++) log.push({h0 + h * 3600, 0.1f, 3600});
    CHECK(log.ack(h0 + 2 * 3600));
    CHECK(log.count == 2 && log.closed[0].t == h0 + 3 * 3600);
    CHECK(!log.ack(h0));            // already gone: nothing changes
    CHECK(log.ack(0xFFFFFFFFu));
    CHECK(log.count == 0);
    char buf[pixc::kEnergyPayloadMax];
    CHECK(log.format(buf, sizeof(buf), nullptr) == 0);
  }
}

static void testJsonUint() {
  uint32_t v = 0;
  CHECK(pixc::jsonUint("{\"through\":1792333200}", "through", &v) && v == 1792333200u);
  CHECK(pixc::jsonUint("{ \"power_s\" : 120 }", "power_s", &v) && v == 120);
  CHECK(pixc::jsonUint("{\"a\":1,\"power_s\":0}", "power_s", &v) && v == 0);
  CHECK(!pixc::jsonUint("{\"through\":-5}", "through", &v));
  CHECK(!pixc::jsonUint("{\"through\":1.5}", "through", &v));
  CHECK(!pixc::jsonUint("{\"through\":\"7\"}", "through", &v));
  CHECK(!pixc::jsonUint("{\"through\":4294967296}", "through", &v));
  CHECK(!pixc::jsonUint("{\"other\":7}", "through", &v));
  CHECK(!pixc::jsonUint("", "through", &v));
  CHECK(!pixc::jsonUint(nullptr, "through", &v));
  CHECK(pixc::clampLiveSeconds(0) == 10);
  CHECK(pixc::clampLiveSeconds(120) == 120);
  CHECK(pixc::clampLiveSeconds(100000) == 300);
}

// ---------------------------------------------------------------------------------------------
// B2: debug output must never carry the PIN or a password, even on a dev build.
// ---------------------------------------------------------------------------------------------
static void redacts(const char* in, const char* want) {
  char buf[512];
  std::snprintf(buf, sizeof(buf), "%s", in);
  pixc::redactJsonSecrets(buf);
  const bool ok = std::strcmp(buf, want) == 0;
  CHECK(ok);
  if (!ok) std::fprintf(stderr, "  in:   %s\n  got:  %s\n  want: %s\n", in, buf, want);
}

static void testRedaction() {
  // The cloud /cfg payload that carries the rotated PIN (DeviceService.buildCfg).
  redacts(R"({"def":{"bri":191},"um":{"PixcConnect":{"settingsPin":"4821"}}})",
          R"({"def":{"bri":191},"um":{"PixcConnect":{"settingsPin":"****"}}})");
  // The LAN body the app sends with every request.
  redacts(R"({"on":true,"pin":"1234"})", R"({"on":true,"pin":"****"})");
  // MQTT credential push and Wi-Fi provisioning.
  redacts(R"({"if":{"mqtt":{"en":true,"user":"aabbccddeeff","psk":"0123abcd"}}})",
          R"({"if":{"mqtt":{"en":true,"user":"aabbccddeeff","psk":"********"}}})");
  redacts(R"({"nw":{"ins":[{"ssid":"Home","psk":"hunter2"}]}})",
          R"({"nw":{"ins":[{"ssid":"Home","psk":"*******"}]}})");
  // Bare values, whitespace, mixed case, escapes.
  redacts(R"({"PIN" : 1234, "bri":5})", R"({"PIN" : ****, "bri":5})");
  redacts(R"({"password":"a\"b"})", R"({"password":"****"})");
  redacts(R"({"ota":{"pwd":"wledota"}})", R"({"ota":{"pwd":"*******"}})");
  // Values that merely LOOK like secret keys are left alone; so is non-secret data.
  redacts(R"({"ssid":"pin","v":true})", R"({"ssid":"pin","v":true})");
  redacts(R"({"seg":[{"col":[[255,0,0]]}]})", R"({"seg":[{"col":[[255,0,0]]}]})");
  // Truncated input must not read past the terminator.
  redacts(R"({"pin":"12)", R"({"pin":"**)");
  redacts(R"({"pi)", R"({"pi)");
  CHECK(pixc::isSecretKey("mqttPass", 8));
  CHECK(pixc::isSecretKey("lan_secret", 10));
  CHECK(!pixc::isSecretKey("ping", 4));
  CHECK(!pixc::isSecretKey("user", 4));
}

// ---------------------------------------------------------------------------------------------
// S3: per-address backoff and a global ceiling that never locks out a correct PIN elsewhere.
// ---------------------------------------------------------------------------------------------
// An address on 192.168.1.0/24 as lwIP stores it on a little-endian CPU (first octet low byte).
static uint32_t lanIp(uint8_t host) { return 192u | (168u << 8) | (1u << 16) | (uint32_t(host) << 24); }

static void testPinGuardBackoff() {
  pixc::PinGuard g;
  const uint32_t a = lanIp(66);
  uint64_t t = 1000000;
  CHECK(g.mayTry(a, t));
  g.onWrong(a, t);
  uint64_t wait = 0;
  CHECK(!g.mayTry(a, t + 999, &wait));
  CHECK(wait == 1);
  CHECK(g.mayTry(a, t + 1000));
  g.onWrong(a, t + 1000);                       // 2nd: 2 s
  CHECK(!g.mayTry(a, t + 2999));
  CHECK(g.mayTry(a, t + 3000));
  g.onWrong(a, t + 3000);                       // 3rd: 4 s
  CHECK(!g.mayTry(a, t + 6999));
  CHECK(g.mayTry(a, t + 7000));
  g.onRight(a);                                 // a right PIN forgives the address
  g.onWrong(a, t + 7000);
  CHECK(g.mayTry(a, t + 8000));                 // back to 1 s
}

static void testPinGuardOwnerNeverLockedOut() {
  pixc::PinGuard g;
  const uint32_t attacker = lanIp(66), owner = lanIp(20), sync = lanIp(21);
  uint64_t t = 5000;
  int ownerRefused = 0;
  // A day of an attacker guessing as fast as it is allowed, every 100 ms, while the owner's app
  // and Sync talk to the light every second with the right PIN.
  for (uint64_t ms = 0; ms < 24ULL * 3600 * 1000; ms += 100) {
    if (g.mayTry(attacker, t + ms)) g.onWrong(attacker, t + ms);
    if (ms % 1000 == 0) {
      if (g.mayTry(owner, t + ms)) g.onRight(owner); else ownerRefused++;
      if (g.mayTry(sync, t + ms)) g.onRight(sync); else ownerRefused++;
    }
  }
  CHECK(ownerRefused == 0);
}

static void testPinGuardCeiling() {
  // A single address: the backoff alone keeps it to a few dozen guesses a day.
  {
    pixc::PinGuard g;
    int guesses = 0;
    for (uint64_t ms = 0; ms < 24ULL * 3600 * 1000; ms += 100) {
      if (g.mayTry(lanIp(66), ms + 1)) { g.onWrong(lanIp(66), ms + 1); guesses++; }
    }
    std::printf("  single-host attacker: %d wrong guesses/day\n", guesses);
    CHECK(guesses <= 40);
  }
  // Every address of the /24, rotating as fast as allowed: bounded by budget + one per address.
  {
    pixc::PinGuard g;
    int guesses = 0;
    for (uint64_t sec = 0; sec < 24ULL * 3600; sec++) {
      for (int h = 1; h < 255; h++) {
        const uint64_t now = sec * 1000 + 1;
        if (g.mayTry(lanIp(uint8_t(h)), now)) { g.onWrong(lanIp(uint8_t(h)), now); guesses++; }
      }
    }
    std::printf("  whole-/24 attacker:   %d wrong guesses/day\n", guesses);
    CHECK(guesses <= pixc::PinGuard::kBudgetBurst + 96 + 256);
    CHECK(guesses >= 100);                      // and the bound is not vacuous
  }
  // With the budget spent, a fresh host is still heard exactly once.
  {
    pixc::PinGuard g;
    for (int i = 0; i < 40; i++) {
      const uint32_t ip = lanIp(uint8_t(100 + i));
      if (g.mayTry(ip, 10)) g.onWrong(ip, 10);
    }
    CHECK(g.tokens() == 0);
    CHECK(g.mayTry(lanIp(200), 10));            // never failed: evaluated
    g.onWrong(lanIp(200), 10);
    CHECK(!g.mayTry(lanIp(200), 2000));         // failed with no budget: refused until a token
    CHECK(g.mayTry(lanIp(201), 2000));          // a different fresh host: still heard
  }
}

