// L7, L10, L8: the health report never overflows its buffer, and carries the heap figures.
// ---------------------------------------------------------------------------------------------
static void testHealthPayload() {
  // The widest report there can be: an SSID of 32 control bytes, the widest numbers, an over-long
  // version. It has to fill the buffer to the byte and still parse.
  char ssid[33];
  for (int i = 0; i < 32; i++) ssid[i] = '\x01';
  ssid[32] = 0;
  std::string fw(80, 'v');
  pixc::Health h{INT_MIN, INT_MIN, ssid, "255.255.255.255", UINT32_MAX, UINT32_MAX, UINT32_MAX,
                 UINT32_MAX, fw.c_str(), UINT32_MAX};
  char buf[pixc::kHealthPayloadMax];
  const int n = pixc::formatHealthPayload(buf, sizeof(buf), h);
  std::printf("  health report: worst case %d bytes, buffer %zu\n", n, sizeof(buf));
  CHECK(n == static_cast<int>(pixc::kHealthPayloadMax) - 1);    // the bound is exact, not loose
  DynamicJsonDocument doc(2048);
  CHECK(!deserializeJson(doc, buf));
  CHECK(std::strlen(doc["ssid"].as<const char*>()) == 32);
  CHECK(doc["heap_largest"].as<uint32_t>() == UINT32_MAX);
  CHECK(doc["fw_version"].as<std::string>().size() == pixc::kFwVersionMax);
  // A '"' or '\\' in the SSID keeps it valid (audit C2), and the new heap fields are there.
  pixc::Health t{-61, 78, "Bob's \"5G\" \\ net", "192.168.1.20", 180000, 90000, 60000, 3600,
                 "17.0.1-pixc1", 3};
  CHECK(pixc::formatHealthPayload(buf, sizeof(buf), t) > 0);
  DynamicJsonDocument d2(1024);
  CHECK(!deserializeJson(d2, buf));
  CHECK(d2["ssid"] == "Bob's \"5G\" \\ net");
  CHECK(d2["free_heap"] == 180000);
  CHECK(d2["heap_largest"] == 90000);
  CHECK(d2["heap_min"] == 60000);
  CHECK(d2["uptime"] == 3600);
  CHECK(d2["rssi"] == -61 && d2["signal"] == 78);
  CHECK(d2["mqtt_dropped"] == 3);
}

static void testBackoff() {
  // Attempt 0 waits between base/2 and base; each attempt doubles; the cap holds; jitter spans.
  CHECK(pixc::backoffWithJitter(0, 2000, 300000, 0) == 1000);
  CHECK(pixc::backoffWithJitter(0, 2000, 300000, 1000) == 2000);
  CHECK(pixc::backoffWithJitter(0, 2000, 300000, 1001) == 1000);
  CHECK(pixc::backoffWithJitter(3, 2000, 300000, 0) == 8000);
  CHECK(pixc::backoffWithJitter(3, 2000, 300000, 8000) == 16000);
  CHECK(pixc::backoffWithJitter(20, 2000, 300000, 0) == 150000);
  CHECK(pixc::backoffWithJitter(255, 2000, 300000, 0xFFFFFFFFu) <= 300000);
  CHECK(pixc::backoffPlusMinus20(0, 5000, 300000, 0) == 4000);
  CHECK(pixc::backoffPlusMinus20(0, 5000, 300000, 2000) == 6000);
  CHECK(pixc::backoffPlusMinus20(10, 5000, 300000, 0) == 240000);
  for (uint32_t r = 0; r < 50000; r += 13) {
    const uint32_t v = pixc::backoffPlusMinus20(2, 5000, 300000, r);
    CHECK(v >= 16000 && v <= 24000);
  }
  for (uint32_t r = 0; r < 100000; r += 7) {
    const uint32_t v = pixc::backoffWithJitter(5, 2000, 300000, r);
    CHECK(v >= 32000 && v <= 64000);
  }
}

// ---------------------------------------------------------------------------------------------
// C2: the SSID in the health JSON is escaped.
// ---------------------------------------------------------------------------------------------
static void escapes(const char* in, const char* want, size_t cap = 128) {
  char out[128];
  pixc::jsonEscape(in, out, cap);
  const bool ok = std::strcmp(out, want) == 0;
  CHECK(ok);
  if (!ok) std::fprintf(stderr, "  in: %s\n  got: %s\n  want: %s\n", in, out, want);
}

static void testJsonEscape() {
  escapes("Home", "Home");
  escapes("Bob's \"5G\"", "Bob's \\\"5G\\\"");
  escapes("a\\b", "a\\\\b");
  escapes("tab\there", "tab\\there");
  escapes("\x01x", "\\u0001x");
  escapes("வீடு", "வீடு");                     // UTF-8 passes through
  escapes("\"\"\"\"", "\\\"\\\"", 6);      // never splits an escape at the cap
  escapes(nullptr, "");
}

// ---------------------------------------------------------------------------------------------
// P2: the power-cycle factory reset, and factory hotspot data.
// ---------------------------------------------------------------------------------------------
// A boot of the unit as pixc_device.cpp drives the gesture: load from "NVS", boot(), then tick()
// every 10 ms until the power goes at `onMs`. Returns true if the reset was requested.
struct GestureNvs { uint8_t n = 0; bool pend = false; int writes = 0; };
static bool runBoot(GestureNvs& nvs, uint32_t onMs, bool powerUp = true) {
  pixc::ResetGesture g;
  g.n = nvs.n;
  g.pend = nvs.pend;
  auto store = [&]() { nvs.n = g.n; nvs.pend = g.pend; nvs.writes++; };
  if (g.boot(powerUp)) store();
  if (g.reset) return true;
  for (uint32_t t = 300; t < onMs; t += 10) if (g.tick(t)) store();   // first loop a little after boot
  return false;
}

static void testResetGesture() {
  // Five on for 3 s each, then on: that sixth power-on requests the reset, at boot.
  {
    GestureNvs nvs;
    for (int i = 0; i < 5; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(nvs.n == 4 && nvs.pend);
    CHECK(runBoot(nvs, 3600000));
    CHECK(nvs.n == 0 && !nvs.pend);
    CHECK(!runBoot(nvs, 3600000));                 // and only once
  }
  // The same across the window, about 2 s to 5 s, mixed; the power-on after it may be anything.
  {
    GestureNvs nvs;
    const uint32_t on[] = {2000, 5000, 1600, 5900, 2500};
    for (uint32_t ms : on) CHECK(!runBoot(nvs, ms));
    CHECK(runBoot(nvs, 200));
  }
  // A flicker: boots that die before 1.5 s never count, however many there are...
  {
    GestureNvs nvs;
    for (int i = 0; i < 50; i++) CHECK(!runBoot(nvs, 1 + (i * 97) % 1490));
    CHECK(nvs.n == 0 && !nvs.pend);
    // ...and one in the middle of a gesture breaks the chain.
    for (int i = 0; i < 4; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(!runBoot(nvs, 800));
    CHECK(!runBoot(nvs, 3000));
    CHECK(nvs.n == 0 && nvs.pend);                 // one qualifying boot so far, not five
    for (int i = 0; i < 4; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(runBoot(nvs, 3000));                     // five from the flicker is a reset
  }
  // A normal on clears the chain: four short ons, a light left on, four more, on: no reset.
  {
    GestureNvs nvs;
    for (int i = 0; i < 4; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(!runBoot(nvs, 3600000));
    CHECK(nvs.n == 0 && !nvs.pend);
    for (int i = 0; i < 4; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(!runBoot(nvs, 60000));
    CHECK(nvs.n == 0 && !nvs.pend);
    // A normal on from a clean state writes twice (1.5 s and 6 s) and never counts.
    const int before = nvs.writes;
    CHECK(!runBoot(nvs, 3600000));
    CHECK(nvs.writes - before == 2);
  }
  // A slow pattern: ons of 7-10 s each (someone waiting to see the light come up) are not the
  // gesture, and one slow on among fast ones restarts it.
  {
    GestureNvs nvs;
    for (int i = 0; i < 10; i++) CHECK(!runBoot(nvs, 7000 + 300 * i));
    CHECK(nvs.n == 0 && !nvs.pend);
    for (int i = 0; i < 3; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(!runBoot(nvs, 6500));
    for (int i = 0; i < 5; i++) CHECK(!runBoot(nvs, 3000));   // the chain restarts after it
    CHECK(runBoot(nvs, 3000));
  }
  // Grid flicker: 20,000 random outages with on-times from 10 ms to 20 s. A reset happens exactly
  // when the last five on-times all landed in 1.5-6 s, and (printed) that is rare.
  {
    GestureNvs nvs;
    uint32_t lcg = 12345, run = 0;
    int resets = 0;
    for (int i = 0; i < 20000; i++) {
      lcg = lcg * 1664525u + 1013904223u;
      const uint32_t on = 10 + (lcg >> 8) % 20000;
      const bool q = on >= pixc::kGestureMinOnMs && on < pixc::kGestureMaxOnMs;
      const bool r = runBoot(nvs, on);
      CHECK(r == (run == 5));                      // a reset exactly when the last five qualified
      if (r) { resets++; run = 0; continue; }      // (the wipe then starts afresh)
      run = q ? run + 1 : 0;
    }
    std::printf("  random on-times 10 ms-20 s: %d resets in 20000 power-ups\n", resets);
  }
  // Exactly at the edges: 1.5 s is in, 6 s is out.
  {
    GestureNvs nvs;
    for (int i = 0; i < 4; i++) CHECK(!runBoot(nvs, 1510));
    CHECK(nvs.n == 3 && nvs.pend);
    GestureNvs nvs2;
    for (int i = 0; i < 6; i++) CHECK(!runBoot(nvs2, 1490));
    CHECK(nvs2.n == 0 && !nvs2.pend);
    GestureNvs nvs3;
    for (int i = 0; i < 6; i++) CHECK(!runBoot(nvs3, 6010));
    CHECK(nvs3.n == 0 && !nvs3.pend);
  }
  // A crash, watchdog or brownout clears the chain: a crash loop never wipes a unit.
  {
    GestureNvs nvs;
    for (int i = 0; i < 5; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(!runBoot(nvs, 3000, false));
    CHECK(nvs.n == 0);
    for (int i = 0; i < 200; i++) CHECK(!runBoot(nvs, 2500, false));
  }
  // A first loop that comes late (setup ran past 6 s) is a long boot, not a qualifying one.
  {
    pixc::ResetGesture g;
    g.n = 3; g.pend = true;
    g.boot(true);
    CHECK(g.n == 4 && !g.reset);
    CHECK(g.tick(7000));
    CHECK(g.n == 0 && !g.pend);
  }
  // A corrupt stored count clears instead of counting.
  {
    pixc::ResetGesture g;
    g.n = 200; g.pend = true;
    g.boot(true);
    CHECK(g.n == 0 && !g.reset);
  }
}

static void testFactoryData() {
  CHECK(pixc::validApPsk("k7m2q9x4ab"));
  CHECK(!pixc::validApPsk("short"));
  CHECK(!pixc::validApPsk(""));
  CHECK(!pixc::validApPsk(nullptr));
  CHECK(!pixc::validApPsk("tab\there!!"));
  char name[16];
  pixc::hotspotName("aabbccddeeff", name, sizeof(name));
  CHECK(std::strcmp(name, "ePixC-EEFF") == 0);
  pixc::hotspotName("001122334a5b", name, sizeof(name));
  CHECK(std::strcmp(name, "ePixC-4A5B") == 0);
}

// ---------------------------------------------------------------------------------------------
// S6: the signed image's build descriptor is found in a stream and older images are refused.
// ---------------------------------------------------------------------------------------------
static void testDescScanner() {
  static const uint8_t magic[pixc::kBuildMagicLen] = PIXC_BUILD_MAGIC;
  // An "image": noise, a false start of the magic, the descriptor, more noise.
  std::vector<uint8_t> img;
  for (int i = 0; i < 5000; i++) img.push_back(uint8_t(i * 7 + 3));
  img.insert(img.end(), magic, magic + 5);                 // a partial match that must not stick
  img.push_back('x');
  img.insert(img.end(), magic, magic + pixc::kBuildMagicLen);
  const uint32_t build = 123456, sec = 3;
  for (int i = 0; i < 4; i++) img.push_back(uint8_t(build >> (8 * i)));
  for (int i = 0; i < 4; i++) img.push_back(uint8_t(sec >> (8 * i)));
  for (int i = 0; i < 3000; i++) img.push_back(uint8_t(i));
  // Every chunk size, so the descriptor straddles every possible boundary.
  for (size_t chunk = 1; chunk <= 40; chunk++) {
    pixc::DescScanner sc(magic);
    for (size_t o = 0; o < img.size(); o += chunk) sc.feed(img.data() + o, std::min(chunk, img.size() - o));
    CHECK(sc.found());
    CHECK(sc.build() == build);
    CHECK(sc.security() == sec);
  }
  pixc::DescScanner none(magic);
  none.feed(img.data(), 5000);
  CHECK(!none.found());

  CHECK(pixc::otaRefusal(false, 10, 1, 5, 1) != nullptr);
  CHECK(std::strcmp(pixc::otaRefusal(true, 4, 1, 5, 1), "downgrade") == 0);
  CHECK(std::strcmp(pixc::otaRefusal(true, 9, 1, 5, 2), "security downgrade") == 0);
  CHECK(pixc::otaRefusal(true, 5, 1, 5, 1) == nullptr);    // a reinstall of the same build
  CHECK(pixc::otaRefusal(true, 6, 2, 5, 1) == nullptr);
}

// ---------------------------------------------------------------------------------------------
// D466 (founder, 2026-10-20): OTA downloads only from https://api.epixc.in/firmware/.
// ---------------------------------------------------------------------------------------------
static void testOtaUrlAllowed() {
  const char* p = pixc::kOtaUrlPrefixProduction;
  CHECK(std::strcmp(p, "https://api.epixc.in/firmware/") == 0);
  // What the backend sends (FirmwareController: base + "/firmware/<target>/<version>/pixc.bin|sig").
  CHECK(pixc::otaUrlAllowed("https://api.epixc.in/firmware/esp32s3/0.16.0-epixc.3/pixc.bin", p));
  CHECK(pixc::otaUrlAllowed("https://api.epixc.in/firmware/esp32s3/0.16.0-epixc.3/pixc.sig", p));
  CHECK(pixc::otaUrlAllowed("https://api.epixc.in/firmware/PixC_V1/v2_rc1/pixc.bin", p));
  // Another host, scheme, port or path: refused.
  CHECK(!pixc::otaUrlAllowed("https://evil.example/firmware/esp32s3/1/pixc.bin", p));
  CHECK(!pixc::otaUrlAllowed("http://api.epixc.in/firmware/esp32s3/1/pixc.bin", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in:8443/firmware/esp32s3/1/pixc.bin", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/api/v1/firmware/x.bin", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in.evil.example/firmware/a/pixc.bin", p));
  CHECK(!pixc::otaUrlAllowed("https://API.EPIXC.IN/firmware/a/pixc.bin", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmwarex/a/pixc.bin", p));
  // Nothing may follow the prefix but plain segments.
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/../admin/x", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a/../../x", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a/.hidden", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/%2e%2e/x", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a/pixc.bin?x=1", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a/pixc.bin#f", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a@evil.example/pixc.bin", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a\\pixc.bin", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware//a/pixc.bin", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a//pixc.bin", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a/", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a b/pixc.bin", p));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a/pixc.bin\n", p));
  CHECK(!pixc::otaUrlAllowed("", p));
  CHECK(!pixc::otaUrlAllowed(nullptr, p));
  // A bench prefix works the same way; a prefix without the final '/' or an empty one admits nothing.
  CHECK(pixc::otaUrlAllowed("http://192.168.0.12:8080/firmware/esp32s3/1/pixc.bin",
                            "http://192.168.0.12:8080/firmware/"));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware-x/a/pixc.bin", "https://api.epixc.in/firmware"));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a/pixc.bin", "https://api.epixc.in/firmware"));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a/pixc.bin", ""));
  CHECK(!pixc::otaUrlAllowed("https://api.epixc.in/firmware/a/pixc.bin", nullptr));
}

// ---------------------------------------------------------------------------------------------
// L5: every OTA failure word lands on the backend code that tells the customer the truth.
// ---------------------------------------------------------------------------------------------
static void otaCode(const char* raw, const char* want) {
  const char* got = pixc::otaErrorCode(raw);
  const bool ok = got != nullptr && std::strcmp(got, want) == 0;
  CHECK(ok);
  if (!ok) std::fprintf(stderr, "  \"%s\" -> %s, want %s\n", raw, got ? got : "null", want);
}

static void testOtaFailureCodes() {
  namespace f = pixc::ota_fail;
  // The one the audit found: fetching the .sig failed, which says nothing about the image.
  otaCode(f::kSigDownload, "OTA_DOWNLOAD_FAILED");
  otaCode(f::kNoSigUrl, "OTA_FAILED");
  otaCode(f::kSigMismatch, "OTA_SIGNATURE_INVALID");
  otaCode(f::kLowMemory, "OTA_BUSY");
  otaCode(f::kNoSpace, "OTA_NO_SPACE");
  otaCode(f::kRead, "OTA_DOWNLOAD_FAILED");
  otaCode(f::kStalled, "OTA_DOWNLOAD_FAILED");
  otaCode(f::kFlashWrite, "OTA_FLASH_FAILED");
  otaCode(f::kNoDigest, "OTA_FAILED");
  otaCode(f::kFieldTooLong, "OTA_FAILED");
  otaCode(f::kHostNotAllowed, "OTA_FAILED");
  otaCode(f::kShaMismatch, "OTA_CORRUPT_DOWNLOAD");
  otaCode(f::kNoSigningKey, "OTA_UNSIGNED_BUILD");
  otaCode(f::kBadSigningKey, "OTA_UNSIGNED_BUILD");
  otaCode(f::kNotConfirmed, "OTA_BUSY");
  otaCode("http 404", "OTA_DOWNLOAD_FAILED");
  otaCode("tls/connect", "OTA_DOWNLOAD_FAILED");
  otaCode("finalize 9", "OTA_FAILED");
  otaCode(pixc::otaRefusal(false, 0, 0, 0, 0), "OTA_FAILED");              // no build descriptor
  otaCode(pixc::otaRefusal(true, 9, 1, 5, 2), "OTA_DOWNGRADE_REFUSED");      // security downgrade
  otaCode(pixc::otaRefusal(true, 4, 1, 5, 1), "OTA_DOWNGRADE_REFUSED");
  // Every word fits the 48-byte error field of the progress report.
  for (const char* w : {f::kLowMemory, f::kNoSpace, f::kRead, f::kStalled, f::kFlashWrite, f::kNoDigest,
                        f::kFieldTooLong, f::kHostNotAllowed, f::kShaMismatch, f::kSigDownload, f::kNoSigUrl, f::kSigMismatch, f::kNoSigningKey,
                        f::kBadSigningKey, f::kNotConfirmed})
    CHECK(std::strlen(w) < 48);
  // The copy of the backend's table, pinned on its own test inputs (OtaErrorCode.of): whole words,
  // so "already" is not "read" and a weak "signal" is not a "sig".
  otaCode("already up to date", "OTA_FAILED");
  otaCode("weak signal", "OTA_FAILED");
  otaCode("HTTP 500", "OTA_DOWNLOAD_FAILED");
  otaCode("bad sig", "OTA_SIGNATURE_INVALID");
  otaCode("image too large", "OTA_NO_SPACE");
  CHECK(pixc::otaErrorCode("") == nullptr);
  CHECK(pixc::otaErrorCode("  ") == nullptr);
  CHECK(pixc::otaErrorCode(nullptr) == nullptr);
}

static void testPinGuardV2Mode() {
  // Pairing v2: no global ceiling, two free failures, then backoff for that address only.
  pixc::PinGuard g(false, 2);
  const uint32_t a = lanIp(30), b = lanIp(31);
  CHECK(g.mayTry(a, 100)); g.onWrong(a, 100);
  CHECK(g.mayTry(a, 100)); g.onWrong(a, 100);
  CHECK(g.mayTry(a, 100)); g.onWrong(a, 100);          // third in a row: 1 s backoff
  CHECK(!g.mayTry(a, 500));
  CHECK(g.mayTry(a, 1100));
  for (int i = 0; i < 500; i++) {                      // a flood from many addresses...
    const uint32_t ip = lanIp(uint8_t(40 + (i % 200)));
    if (g.mayTry(ip, 2000)) g.onWrong(ip, 2000);
  }
  CHECK(g.mayTry(b, 2000));                            // ...never touches anyone else
}

// D411: certificate dates against the light's clock (pixc::utcSeconds, clockTrusted, certTimeVerdict).
static void testCertDates() {
  using pixc::CertTime;
  // Known instants (Python calendar.timegm).
  CHECK(pixc::utcSeconds(1970, 1, 1, 0, 0, 0) == 0);
  CHECK(pixc::utcSeconds(2000, 3, 1, 0, 0, 0) == 951868800LL);
  CHECK(pixc::utcSeconds(2024, 1, 1, 0, 0, 0) == (int64_t)pixc::kClockValidAfter);
  CHECK(pixc::utcSeconds(2024, 2, 29, 23, 59, 59) == 1709251199LL);       // a leap day
  CHECK(pixc::utcSeconds(2026, 10, 20, 12, 34, 56) == 1792499696LL);
  CHECK(pixc::utcSeconds(2035, 6, 4, 11, 4, 38) == 2064567878LL);         // ISRG Root X1 notAfter
  CHECK(pixc::utcSeconds(2100, 3, 1, 0, 0, 0) == 4107542400LL);           // 2100 is not a leap year
  CHECK(pixc::utcSeconds(1950, 1, 1, 0, 0, 0) == -631152000LL);           // UTCTime's first year
  CHECK(pixc::utcSeconds(9999, 12, 31, 23, 59, 59) == 253402300799LL);    // GeneralizedTime's last
  // Every day from 1950 to 2150 is exactly 86400 s after the one before (calendar walk).
  {
    static const int dim[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int64_t prev = pixc::utcSeconds(1950, 1, 1, 0, 0, 0);
    int bad = 0;
    for (int y = 1950; y <= 2150; y++)
      for (int m = 1; m <= 12; m++) {
        const bool leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
        const int days = dim[m - 1] + (m == 2 && leap ? 1 : 0);
        for (int d = 1; d <= days; d++) {
          if (y == 1950 && m == 1 && d == 1) continue;
          const int64_t t = pixc::utcSeconds(y, m, d, 0, 0, 0);
          if (t - prev != 86400) bad++;
          prev = t;
        }
      }
    CHECK(bad == 0);
  }
  // Out-of-range fields are unreadable.
  CHECK(pixc::utcSeconds(1949, 12, 31, 0, 0, 0) == pixc::kBadTime);
  CHECK(pixc::utcSeconds(2026, 13, 1, 0, 0, 0) == pixc::kBadTime);
  CHECK(pixc::utcSeconds(2026, 0, 1, 0, 0, 0) == pixc::kBadTime);
  CHECK(pixc::utcSeconds(2026, 1, 32, 0, 0, 0) == pixc::kBadTime);
  CHECK(pixc::utcSeconds(2026, 1, 1, 24, 0, 0) == pixc::kBadTime);
  CHECK(pixc::utcSeconds(2026, 1, 1, 0, 60, 0) == pixc::kBadTime);

  // A leaf issued 2026-09-01 for 90 days; the image was committed 2026-10-01.
  const int64_t from = pixc::utcSeconds(2026, 9, 1, 0, 0, 0);
  const int64_t to = pixc::utcSeconds(2026, 11, 30, 0, 0, 0);
  const int64_t floor = pixc::utcSeconds(2026, 10, 1, 0, 0, 0);
  const int64_t day = 86400;
  // The clock is trusted only at or past both 2024-01-01 and the image's commit time.
  CHECK(!pixc::clockTrusted(120, floor));                   // seconds since boot: SNTP not yet
  CHECK(!pixc::clockTrusted(floor - 1, floor));             // before the image existed: wrong
  CHECK(pixc::clockTrusted(floor, floor));
  CHECK(!pixc::clockTrusted(pixc::kClockValidAfter - 1, 0)); // no floor known: 2024-01-01 still
  CHECK(pixc::clockTrusted(pixc::kClockValidAfter, 0));
  // Trusted clock: mbedTLS's rule, notBefore <= now <= notAfter, no grace.
  CHECK(pixc::certTimeVerdict(from, to, floor + day, floor) == CertTime::Ok);
  CHECK(pixc::certTimeVerdict(from, to, to, floor) == CertTime::Ok);          // the last second
  CHECK(pixc::certTimeVerdict(from, to, to + 1, floor) == CertTime::Expired);
  CHECK(pixc::certTimeVerdict(from, to, to + 400 * day, floor) == CertTime::Expired);
  const int64_t laterFrom = floor + 10 * day;                                  // issued after the image
  CHECK(pixc::certTimeVerdict(laterFrom, laterFrom + 90 * day, laterFrom - 1, floor) == CertTime::NotYetValid);
  CHECK(pixc::certTimeVerdict(laterFrom, laterFrom + 90 * day, laterFrom, floor) == CertTime::Ok);
  // No trusted clock yet: the connection is not deferred, and only a certificate that expired
  // before the image was committed is refused - whatever the clock says (an attacker's NTP, or none).
  CHECK(pixc::certTimeVerdict(from, to, 120, floor) == CertTime::Ok);
  CHECK(pixc::certTimeVerdict(laterFrom, laterFrom + 90 * day, 120, floor) == CertTime::Ok);  // notBefore unknowable
  const int64_t oldTo = floor - 5 * day;                                       // a cert of the summer
  CHECK(pixc::certTimeVerdict(oldTo - 90 * day, oldTo, 120, floor) == CertTime::Expired);
  CHECK(pixc::certTimeVerdict(oldTo - 90 * day, oldTo, floor - 6 * day, floor) == CertTime::Expired);  // clock wound back
  CHECK(pixc::certTimeVerdict(oldTo - 90 * day, oldTo, floor + day, floor) == CertTime::Expired);
  CHECK(pixc::certTimeVerdict(oldTo - 90 * day, oldTo, 120, 0) == CertTime::Ok);  // no floor: as before D411
  // Roots: valid for decades, and their notBefore is long past.
  const int64_t x1From = pixc::utcSeconds(2015, 6, 4, 11, 4, 38), x1To = pixc::utcSeconds(2035, 6, 4, 11, 4, 38);
  CHECK(pixc::certTimeVerdict(x1From, x1To, floor + day, floor) == CertTime::Ok);
  CHECK(pixc::certTimeVerdict(x1From, x1To, x1To + 1, floor) == CertTime::Expired);   // X1 after 2035
  // Unreadable dates fail closed, with or without a clock.
  CHECK(pixc::certTimeVerdict(pixc::kBadTime, to, floor + day, floor) == CertTime::Expired);
  CHECK(pixc::certTimeVerdict(from, pixc::kBadTime, 120, floor) == CertTime::Expired);
}

